/* Two's-complement value of a 32-bit pattern, without the implementation-
 * defined conversion of a value above INT32_MAX. */
static inline int32_t as_signed(uint32_t x) {
    return x<=(uint32_t)INT32_MAX?(int32_t)x:-(int32_t)(~x)-1;
}
/* |a| as uint32, branch-free (|INT32_MIN| = 2^31). */
static inline uint32_t magnitude(uint32_t a) {
    const uint32_t s=0u-(a>>31);
    return (a^s)-s;
}
/* One row, branch-free; a failure makes *bad nonzero.
 *   sum = r . eye exactly (each product below 2^47, the sum below 2^49), as
 *         two 32-bit halves hi:lo;
 *   floor(sum / 2^12) fits int32 iff hi is in [-2^11, 2^11), that is
 *         (hi + 2^11) mod 2^32 < 2^12;
 *   q = floor(sum / 2^12) = hi << 20 | lo >> 12 (mod 2^32), t = -q;
 *   the row bound 32768 * sum|r| + |q| <= INT32_MAX, where sum|r| << 15 <
 *         2^32 and |q| <= 2^31: the 33-bit total exceeds INT32_MAX iff its
 *         low word has bit 31 set or the addition carried. q = -2^31 has
 *         |q| = 2^31 and fails here, so -q never overflows. */
static inline __attribute__((always_inline)) int32_t row_t(int32_t r0,int32_t r1,int32_t r2,
    int32_t e0,int32_t e1,int32_t e2,uint32_t *bad) {
    const int64_t sum=(int64_t)r0*e0+(int64_t)r1*e1+(int64_t)r2*e2;
    const uint64_t u=(uint64_t)sum;
    const uint32_t hi=(uint32_t)(u>>32),lo=(uint32_t)u;
    const uint32_t q=(hi<<20)|(lo>>12);
    const uint32_t s=(magnitude((uint32_t)r0)+magnitude((uint32_t)r1)+magnitude((uint32_t)r2))<<15;
    const uint32_t total=s+magnitude(q);
    *bad|=((hi+UINT32_C(0x800))&UINT32_C(0xFFFFF000))|(total&UINT32_C(0x80000000))|(uint32_t)(total<s);
    return as_signed(0u-q);
}

/* The view-contract-1 validity rule, without a library call. */
static inline bool view_ok(const sh2z_view_t *v) {
    if(v->focal_x<=0 || v->focal_y<=0 || v->near_z<=0 || v->far_z<=v->near_z ||
       v->clip[0]>v->clip[2] || v->clip[1]>v->clip[3])return false;
    for(unsigned i=0;i<3;++i) {
        const uint32_t s=(magnitude((uint32_t)v->r[i][0])+magnitude((uint32_t)v->r[i][1])+
            magnitude((uint32_t)v->r[i][2]))<<15;
        const uint32_t total=s+magnitude((uint32_t)v->t[i]);
        if((total>>31) || total<s)return false;
    }
    return true;
}

bool sh2z_view_place_q12(sh2z_view_t *v,const int32_t eye_q12[3]) {
    if(!v || !eye_q12 || !view_ok(v))return false;
    uint32_t bad=0;
    const int32_t e0=eye_q12[0],e1=eye_q12[1],e2=eye_q12[2];
    int32_t t[3];
    for(unsigned i=0;i<3;++i)t[i]=row_t(v->r[i][0],v->r[i][1],v->r[i][2],e0,e1,e2,&bad);
    if(bad)return false;
    v->t[0]=t[0];v->t[1]=t[1];v->t[2]=t[2];
    return true;
}

/* round(b / 65536), ties away from zero: floor((b + 32767 + [b >= 0]) /
 * 65536), from the unsigned sum. The sum wraps (bit 31 set while b >= 0)
 * exactly when the result would be 32768, so that bit goes into *bad. The
 * floor of the sum is its top half read as a signed 16-bit value. */
static inline __attribute__((always_inline)) int32_t round_u30(int32_t b,uint32_t *bad) {
    const uint32_t u=(uint32_t)b;
    const uint32_t s=u+UINT32_C(32767)+((u>>31)^1u);
    *bad|=s&~u&UINT32_C(0x80000000);
    const uint32_t top=s>>16;
    return (int32_t)(top&0x7FFFu)-(int32_t)(top&0x8000u);
}
/* floor((scale * c + 2^19) / 2^20) for scale > 0, c < 2^30: the product is
 * below 2^61. Fails when the result is 0 or above INT32_MAX. */
static inline bool focal_of(int32_t scale,uint32_t c,int32_t *f) {
    if(scale<=0)return false;
    const uint64_t p=(uint64_t)(uint32_t)scale*c+UINT32_C(0x80000);
    const uint32_t hi=(uint32_t)(p>>32),lo=(uint32_t)p;
    const uint32_t q=(hi<<12)|(lo>>20);
    if(hi>=UINT32_C(0x80000) || !q)return false;   /* result >= 2^31, or 0 */
    *f=(int32_t)q;
    return true;
}
/* floor(c / 65536) as int16, without a signed shift. */
static inline int16_t floor16(int32_t c) {
    const uint32_t top=(uint32_t)c>>16;
    return (int16_t)((int32_t)(top&0x7FFFu)-(int32_t)(top&0x8000u));
}

bool sh2z_view_from_camera30(sh2z_view_center_t *out,const int32_t basis_u30[9],
    const int32_t eye_q12[3],const sh2z_view_lens_t *lens) {
    if(!out || !basis_u30 || !eye_q12 || !lens)return false;
    const int32_t fov=lens->fov_q16;
    if((uint32_t)fov-5760u>11790719u-5760u)return false;
    /* h = floor(floor((fov + 5760) / 256) / 45). With y < 2^16,
     * floor(y * 95443718 / 2^32) is floor(y / 45): 95443718 * 45 = 2^32 + 14
     * and y * 14 < 2^32. */
    const uint32_t y=((uint32_t)fov+5760u)>>8;
    const uint32_t h=(uint32_t)(((uint64_t)y*UINT32_C(95443718))>>32);
    const uint32_t c=(uint32_t)cot_q20[h];
    int32_t fx,fy;
    if(!focal_of(lens->scale_x16,c,&fx) || !focal_of(lens->scale_y16,c,&fy))return false;
    const int32_t near_q12=lens->near_q12,far_q12=lens->far_q12;
    if(near_q12<=0 || far_q12<=near_q12 || far_q12>INT32_MAX/4)return false;
    const int16_t c0=lens->clip[0],c1=lens->clip[1],c2=lens->clip[2],c3=lens->clip[3];
    if(c0>c2 || c1>c3)return false;
    uint32_t bad=0;
    const int32_t e0=eye_q12[0],e1=eye_q12[1],e2=eye_q12[2];
    int16_t r[9];
    int32_t t[3];
    for(unsigned i=0;i<3;++i) {
        const int32_t a=round_u30(basis_u30[3*i],&bad),b=round_u30(basis_u30[3*i+1],&bad),
            d=round_u30(basis_u30[3*i+2],&bad);
        r[3*i]=(int16_t)a;r[3*i+1]=(int16_t)b;r[3*i+2]=(int16_t)d;
        t[i]=row_t(a,b,d,e0,e1,e2,&bad);
    }
    if(bad)return false;
    const int32_t cx=lens->center_x16,cy=lens->center_y16;
    sh2z_view_t *v=&out->view;
    for(unsigned i=0;i<9;++i)v->r[i/3][i%3]=r[i];
    v->t[0]=t[0];v->t[1]=t[1];v->t[2]=t[2];
    v->focal_x=fx;v->focal_y=fy;
    v->center_x=floor16(cx);v->center_y=floor16(cy);
    v->near_z=near_q12*4;v->far_z=far_q12*4;
    v->clip[0]=c0;v->clip[1]=c1;v->clip[2]=c2;v->clip[3]=c3;
    out->center_x16=cx;out->center_y16=cy;
    return true;
}
